def compare_versions(a: str, b: str) -> int:
    def parse_version(v):
        # Remove build metadata (everything after +)
        v = v.split('+')[0]

        # Split into base version and pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            base = v
            prerelease_parts = None

        # Parse major.minor.patch
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, prerelease_parts)

    def is_numeric(s):
        return s.isdigit()

    def compare_prerelease(pre_a, pre_b):
        # If both have no pre-release, they're equal (for this part)
        if pre_a is None and pre_b is None:
            return 0

        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers one by one
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                # a has fewer identifiers, so a < b
                return -1
            if i >= len(pre_b):
                # b has fewer identifiers, so a > b
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            num_a = is_numeric(id_a)
            num_b = is_numeric(id_b)

            if num_a and num_b:
                # Both numeric: compare numerically
                val_a = int(id_a)
                val_b = int(id_b)
                if val_a < val_b:
                    return -1
                elif val_a > val_b:
                    return 1
            elif num_a:
                # Only a is numeric: numeric < non-numeric
                return -1
            elif num_b:
                # Only b is numeric: non-numeric > numeric
                return 1
            else:
                # Both non-numeric: compare lexically (ASCII order)
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major.minor.patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release
    return compare_prerelease(pre_a, pre_b)
